    "\n"
    "const fetchers = {\n"
    "  memory:    {path:'/v1/memory',    out:'memory-out'},\n"
    "  snapshots: {path:'/v1/snapshots', out:'snapshots-out'},\n"
    "  trace:     {path:'/v1/trace',     out:'trace-out'},\n"
    "  usage:     {path:'/v1/usage',     out:'usage-out'},\n"
    "  plugins:   {path:'/v1/plugins',   out:'plugins-out'},\n"
    "  skills:    {path:'/v1/skills',    out:'skills-out'},\n"
    "  cluster:   {path:'/v1/cluster',   out:'cluster-out'},\n"
    "  metrics:   {path:'/metrics',      out:'metrics-out'},\n"
    "};\n"
    "\n"
    "/* ================= 数据加载 ================= */\n"
    "\n"
    "async function load(panel){\n"
    "  if(panel === 'models') return loadModels();\n"
    "  if(panel === 'dashboard') return loadDashboard();\n"
    "  if(panel === 'im') return renderIm();\n"
    "  if(panel === 'agents') return loadAgents();\n"
    "  if(panel === 'mcp') return loadMcp();\n"
    "  if(panel === 'skills') return loadSkillsMarket();\n"
    "  if(panel === 'plugins') return loadPluginMarket();\n"
    "  if(panel === 'snapshots') return loadSnapshots();\n"
    "  if(panel === 'chat') return loadChat();\n"
    "  if(panel === 'policy') return loadPolicy();\n"
    "  if(panel === 'flow') return loadFlow();\n"
    "  if(panel === 'metrics'){\n"
    "    const r = await call('GET', '/metrics');\n"
    "    const el = $('metrics-out'); if(el) el.textContent = r.text;\n"
    "    return;\n"
    "  }\n"
    "  const f = fetchers[panel];\n"
    "  if(!f) return;\n"
    "  const r = await call('GET', f.path);\n"
    "  const el = $(f.out); if(el) renderJSON(r.obj, el);\n"
    "}\n"
    "\n"
    "/* ================= Snapshots ================= */\n"
    "\n"
    "async function loadSnapshots(){\n"
    "  const r = await call('GET', '/v1/snapshots');\n"
    "  const el = $('snapshots-out'); if(el) renderJSON(r.obj, el);\n"
    "  await loadSnapshotCfg();\n"
    "}\n"
    "\n"
    "async function loadSnapshotCfg(){\n"
    "  const r = await call('GET', '/v1/config/snapshot');\n"
    "  const el = $('snap-max'); if(!el) return;\n"
    "  const v = (r.obj && typeof r.obj.max_file === 'number' && r.obj.max_file >= 0) ? r.obj.max_file : 67108864;\n"
    "  el.value = v === 0 ? 0 : Math.round(v / 1048576);\n"
    "  const st = $('snap-max-msg'); if(st) st.textContent = '';\n"
    "}\n"
    "\n"
    "async function saveSnapshotCfg(){\n"
    "  const el = $('snap-max'); if(!el) return;\n"
    "  const st = $('snap-max-msg');\n"
    "  const mb = parseInt(el.value, 10);\n"
    "  if(isNaN(mb) || mb < 0){ if(st) st.textContent = '请输入 ≥ 0 的整数（0 = 不限制）'; return; }\n"
    "  const r = await call('POST', '/v1/config/snapshot', {max_file: mb * 1048576});\n"
    "  if(st) st.textContent = (r.status === 200 && r.obj && r.obj.ok) ? '已保存' : ('失败: ' + (r.text || ('HTTP ' + r.status)).slice(0, 80));\n"
    "}\n"
    "\n"
    "/* ================= Agents ================= */\n"
    "\n"
    "let AGENTS = [];\n"
    "\n"
    "async function loadAgents(){\n"
    "  const r = await call('GET', '/v1/agents');\n"
    "  const box = $('agents-out2');\n"
    "  if(!box) return;\n"
    "  const obj = (r.obj && typeof r.obj === 'object') ? r.obj : {};\n"
    "  AGENTS = Array.isArray(obj.agents) ? obj.agents : [];\n"
    "  let html = '<div class=\"table-wrap\"><table><thead><tr><th>Agent</th><th>Role</th><th>Model</th></tr></thead><tbody>';\n"
    "  if(!AGENTS.length) html += '<tr><td colspan=\"3\" class=\"muted\">（暂无 agent，先创建一个）</td></tr>';\n"
    "  AGENTS.forEach(a => {\n"
    "    const model = [a.provider, a.model].filter(Boolean).join(' / ') || '（当前激活）';\n"
    "    html += '<tr><td>' + esc(a.name || '') + '</td><td>' + esc(a.role || '') + '</td><td class=\"muted\">' + esc(model) + '</td></tr>';\n"
    "  });\n"
    "  html += '</tbody></table></div>';\n"
    "  html += '<div class=\"hint\" style=\"margin-top:8px\">共享黑板 facts:</div><pre>' + esc(JSON.stringify(obj.facts || {}, null, 2)) + '</pre>';\n"
    "  box.innerHTML = html;\n"
    "}\n"
    "\n"
    "function agentAdd(){\n"
    "  const name = $('agent-name').value.trim();\n"
    "  const role = $('agent-role').value.trim();\n"
    "  const provider = $('agent-provider').value.trim();\n"
    "  const model = $('agent-model').value.trim();\n"
    "  const st = $('agent-stat');\n"
    "  if(!name){ if(st) st.textContent = '需要 name'; return; }\n"
    "  const body = {name, role};\n"
    "  if(provider) body.provider = provider;\n"
    "  if(model) body.model = model;\n"
    "  call('POST', '/v1/agents', body).then(r => {\n"
    "    if(st) st.textContent = (r.status < 300) ? '✔ 已创建' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "    if(r.status < 300){ $('agent-name').value = ''; $('agent-role').value = ''; $('agent-provider').value = ''; $('agent-model').value = ''; loadAgents(); }\n"
    "  });\n"
    "}\n"
    "\n"
    "function agentPost(){\n"
    "  const name = $('agent-post-name').value.trim();\n"
    "  const key = $('agent-post-key').value.trim();\n"
    "  const val = $('agent-post-val').value.trim();\n"
    "  if(!name || !key || !val) return;\n"
    "  call('POST', '/v1/agents/' + encodeURIComponent(name) + '/post', {key, value: val}).then(r => {\n"
    "    if(r.obj && r.obj.ok){ $('agent-post-key').value = ''; $('agent-post-val').value = ''; loadAgents(); }\n"
    "  });\n"
    "}\n"
    "\n"
    "/* ================= MCP ================= */\n"
    "\n"
    "let MCP_CONNS = [];\n"
    "\n"
    "async function loadMcp(){\n"
    "  const r = await call('GET', '/v1/mcp');\n"
    "  const box = $('mcp-list');\n"
    "  if(!box) return;\n"
    "  MCP_CONNS = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!MCP_CONNS.length){\n"
    "    box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（暂无连接，先添加一个）</span>';\n"
    "  } else {\n"
    "    box.innerHTML = '<div class=\"table-wrap\"><table><thead><tr><th>Name</th><th>Transport</th><th>Target</th><th>Tools</th><th>Token</th><th></th></tr></thead><tbody>' +\n"
    "      MCP_CONNS.map((c, i) => '<tr><td>' + esc(c.name) + '</td><td>' + esc(c.transport || 'http') + '</td>' +\n"
    "        '<td class=\"muted\">' + esc((c.transport === 'stdio') ? ((c.command || '') + ' ' + (c.args || '')) : c.url) + '</td>' +\n"
    "        '<td>' + (typeof c.tools === 'number' ? c.tools : '—') + '</td>' +\n"
    "        '<td>' + (c.has_token ? '已设置' : '—') + '</td>' +\n"
    "        '<td><button class=\"sec sm danger\" onclick=\"mcpDelete(' + i + ')\">Delete</button> ' +\n"
    "        '<button class=\"sec sm\" onclick=\"mcpSync()\">Sync</button></td></tr>').join('') +\n"
    "      '</tbody></table></div>';\n"
    "  }\n"
    "  loadMcpPlaza();\n"
    "}\n"
    "\n"
    "let MCP_PLAZA = [];\n"
    "\n"
    "async function loadMcpPlaza(){\n"
    "  const box = $('mcp-plaza');\n"
    "  if(!box) return;\n"
    "  const r = await call('GET', '/v1/catalog/mcp');\n"
    "  MCP_PLAZA = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!MCP_PLAZA.length){ box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（目录为空）</span>'; return; }\n"
    "  box.innerHTML = MCP_PLAZA.map((m, i) =>\n"
    "    '<div class=\"item\"><h3>' + esc(m.name) + (m.repo ? ' <a class=\"tag\" href=\"' + esc(m.repo) + '\" target=\"_blank\" rel=\"noopener\">GitHub</a>' : '') + '</h3><p>' + esc(m.description) + '</p>' +\n"
    "    '<div class=\"url\">' + esc(m.transport === 'stdio' ? ((m.command || '') + ' ' + (m.args || '')) : m.url) + '</div>' +\n"
    "    '<div class=\"hint\">' + (m.needs_local ? '需本地运行 · ' : '') + esc(m.key_hint || '') + '</div>' +\n"
    "    '<button class=\"sec sm\" onclick=\"mcpPlazaUse(' + i + ')\">添加连接</button></div>'\n"
    "  ).join('');\n"
    "}\n"
    "\n"
    "async function mcpPlazaUse(i){\n"
    "  const m = MCP_PLAZA[i]; if(!m) return;\n"
    "  toast('添加 MCP 连接 ' + m.id + ' …');\n"
    "  const body = {name: m.id, transport: m.transport || 'http'};\n"
    "  if(m.transport === 'stdio'){\n"
    "    body.command = m.command || '';\n"
    "    body.args = m.args || '';\n"
    "    if(!body.command){ toast('该条目缺少 stdio 命令'); return; }\n"
    "  } else {\n"
    "    body.url = m.url;\n"
    "  }\n"
    "  if(m.token && m.token_hint) body.token = m.token;\n"
    "  if(m.needs_token && !body.token){\n"
    "    const tok = prompt('该 MCP 服务器需要凭据，请输入 ' + (m.key_hint || 'token') + '：');\n"
    "    if(!tok){ toast('已取消（未填 token）'); return; }\n"
    "    body.token = tok.trim();\n"
    "    if(!body.token){ toast('已取消（未填 token）'); return; }\n"
    "  }\n"
    "  const r = await call('POST', '/v1/mcp', body);\n"
    "  if(r.status < 300) toast('✔ 已添加连接 ' + m.id);\n"
    "  else toast('添加失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadMcp();\n"
    "}\n"
    "\n"
    "function mcpAdd(){\n"
    "  const name = $('mcp-name').value.trim();\n"
    "  const transport = $('mcp-transport') ? $('mcp-transport').value : 'http';\n"
    "  const url = $('mcp-url').value.trim();\n"
    "  const command = $('mcp-command') ? $('mcp-command').value.trim() : '';\n"
    "  const args = $('mcp-args') ? $('mcp-args').value.trim() : '';\n"
    "  const token = $('mcp-token').value.trim();\n"
    "  const st = $('mcp-stat');\n"
    "  if(!name){ if(st) st.textContent = '需要 name'; return; }\n"
    "  if(transport === 'http' && !url){ if(st) st.textContent = 'http 传输需要 url'; return; }\n"
    "  if(transport === 'stdio' && !command){ if(st) st.textContent = 'stdio 传输需要 command'; return; }\n"
    "  const body = {name, transport};\n"
    "  if(transport === 'http') body.url = url; else { body.command = command; if(args) body.args = args; }\n"
    "  if(token) body.token = token;\n"
    "  call('POST', '/v1/mcp', body).then(r => {\n"
    "    if(st) st.textContent = (r.status < 300) ? '✔ 已添加' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "    if(r.status < 300){ $('mcp-name').value = ''; $('mcp-url').value = ''; $('mcp-command').value = ''; $('mcp-args').value = ''; $('mcp-token').value = ''; loadMcp(); }\n"
    "  });\n"
    "}\n"
    "\n"
    "async function mcpSync(){\n"
    "  toast('重新发现 MCP 工具…');\n"
    "  const r = await call('POST', '/v1/mcp/sync', {});\n"
    "  if(r.status < 300) toast('✔ 已重新发现 ' + ((r.obj && r.obj.registered) || 0) + ' 个工具');\n"
    "  else toast('同步失败: HTTP ' + r.status);\n"
    "  loadMcp();\n"
    "}\n"
    "\n"
    "function mcpDelete(i){\n"
    "  const c = MCP_CONNS[i]; if(!c) return;\n"
    "  call('DELETE', '/v1/mcp/' + encodeURIComponent(c.name)).then(() => loadMcp());\n"
    "}\n"
    "\n"
    "async function loadDashboard(){\n"
    "  const [ag, mem, plg, im] = await Promise.all([\n"
    "    call('GET', '/v1/agents'),\n"
    "    call('GET', '/v1/memory'),\n"
    "    call('GET', '/v1/plugins'),\n"
    "    call('GET', '/v1/im/sessions'),\n"
    "  ]);\n"
    "  const st = $('dashStats');\n"
    "  if(st){\n"
    "    const agents  = Array.isArray(ag.obj) ? ag.obj.length : (ag.obj && ag.obj.agents ? ag.obj.agents.length : 0);\n"
    "    const wmem    = (mem.obj && Array.isArray(mem.obj.working)) ? mem.obj.working.length : 0;\n"
    "    const plugins = (plg.obj && plg.obj.plugins && Array.isArray(plg.obj.plugins)) ? plg.obj.plugins.length\n"
    "                  : (Array.isArray(plg.obj) ? plg.obj.length : 0);\n"
    "    const ims     = (im.obj && im.obj.total_messages) ? im.obj.total_messages : 0;\n"
    "    const cells = st.querySelectorAll('.stat .num');\n"
    "    if(cells.length >= 6){\n"
    "      cells[0].textContent = '0.1.0';\n"
    "      cells[1].textContent = 'mock';\n"
    "      cells[2].textContent = agents;\n"
    "      cells[3].textContent = wmem;\n"
    "      cells[4].textContent = plugins;\n"
    "      cells[5].textContent = ims;\n"
    "    }\n"
    "  }\n"
    "  const el = $('dash-out');\n"
    "  if(el){\n"
    "    const payload = {\n"
    "      agents: ag.obj, memory: mem.obj, plugins: plg.obj, im: im.obj\n"
    "    };\n"
    "    renderJSON(payload, el);\n"
    "  }\n"
    "}\n"
    "\n"
    "async function rollback(){\n"
    "  const r = await call('POST', '/v1/snapshots/rollback');\n"
    "  renderJSON(r.obj, $('snapshots-out'));\n"
    "  load('snapshots');\n"
    "}\n"
    "\n"
    "async function runSkill(){\n"
    "  const name = $('skillname').value.trim();\n"
    "  if(!name) return;\n"
    "  const r = await call('POST', '/v1/skills/run', {name});\n"
    "  renderJSON(r.obj, $('skills-out'));\n"
    "}\n"
    "\n"
    "/* ================= Skills 市场 / 发布 ================= */\n"
    "let SKILL_MARKET = {templates:[], installed:[]};\n"
    "\n"
    "async function loadSkillsMarket(){\n"
    "  const r = await call('GET', '/v1/skills');\n"
    "  if($('skills-out')) renderJSON(r.obj, $('skills-out'));\n"
    "  const m = await call('GET', '/v1/skills/market');\n"
    "  SKILL_MARKET = (m.obj && typeof m.obj === 'object') ? m.obj : {templates:[], installed:[]};\n"
    "  const box = $('skill-market'); if(!box) return;\n"
    "  const t = SKILL_MARKET.templates || [], inst = SKILL_MARKET.installed || [], gh = SKILL_MARKET.github || [];\n"
    "  let html = '<div class=\"sub\">市场模板（点击安装）</div>' +\n"
    "    (t.length ? t.map((x,i) =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      (x.installed ? ' <span class=\"tag\">已安装</span>' : '') +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      '<button class=\"sec sm\" onclick=\"installSkill(' + i + ')\">' + (x.installed ? '重装/更新' : '安装') + '</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">GitHub 热门应用（点击安装 / 查看仓库）</div>' +\n"
    "    (gh.length ? gh.map(x =>\n"
    "      '<div class=\"item\"><b><a href=\"' + esc(x.repo) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.name) + '</a></b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      (x.winget_id ? '<button class=\"sec sm\" onclick=\"ghInstall(\\'' + esc(x.name) + '\\')\">安装（winget）</button>' : '') + '</div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">已安装（可删除）</div>' +\n"
    "    (inst.length ? inst.map(x =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b> <span class=\"muted\">' + esc(x.kind) + '</span> ' +\n"
    "      '<button class=\"sec sm danger\" onclick=\"deleteSkill(\\'' + x.name + '\\')\">删除</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  box.innerHTML = html;\n"
    "}\n"
    "\n"
    "async function installSkill(i){\n"
    "  const t = (SKILL_MARKET.templates || [])[i]; if(!t) return;\n"
    "  const r = await call('POST', '/v1/skills/publish',\n"
    "    {name:t.name, description:t.description, kind:t.kind, body:t.body});\n"
    "  if(r.obj && r.obj.ok) toast('已' + (t.installed ? '更新 ' : '安装 ') + t.name);\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "async function ghInstall(name){\n"
    "  toast('启动安装 ' + name + '（后台 winget）…');\n"
    "  const r = await call('POST', '/v1/tools/gh-install', {name});\n"
    "  if(r.obj && r.obj.ok) toast(name + ' 后台安装已启动，完成后可在 shell 里直接使用');\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "}\n"
    "\n"
    "async function deleteSkill(n){\n"
    "  await call('DELETE', '/v1/skills/' + encodeURIComponent(n));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "async function publishSkill(){\n"
    "  const name = $('sk-name').value.trim(), body = $('sk-body').value;\n"
    "  if(!name || !body){ if($('sk-stat')) $('sk-stat').textContent = '需要 name 和 body'; return; }\n"
    "  const r = await call('POST', '/v1/skills/publish',\n"
    "    {name, description:$('sk-desc').value, kind:$('sk-kind').value, body});\n"
    "  if($('sk-stat')) $('sk-stat').textContent = (r.obj && r.obj.ok) ? '已发布' : ('失败 ' + ((r.obj && r.obj.error) || r.status));\n"
    "  if(r.obj && r.obj.ok){ $('sk-name').value=''; $('sk-desc').value=''; $('sk-body').value=''; }\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "/* ================= Plugins 市场 / 发布 ================= */\n"
    "async function loadPluginMarket(){\n"
    "  const m = await call('GET', '/v1/plugins/market');\n"
    "  const box = $('plugin-market'); if(!box) return;\n"
    "  const t = (m.obj && m.obj.templates) || [];\n"
    "  const gh = (m.obj && m.obj.github) || [];\n"
    "  const reg = await call('GET', '/v1/plugins');\n"
    "  const inst = reg.obj ? Object.keys(reg.obj) : [];\n"
    "  let html = '<div class=\"sub\">示例模板</div>' +\n"
    "    (t.length ? t.map(x =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b><div class=\"hint\">' + esc(x.description || '') + '</div></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">GitHub 热门应用（点击查看仓库）</div>' +\n"
    "    (gh.length ? gh.map(x =>\n"
    "      '<div class=\"item\"><b><a href=\"' + esc(x.repo) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.name) + '</a></b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">已发布插件（可下架）</div>' +\n"
    "    (inst.length ? inst.map(n =>\n"
    "      '<div class=\"item\"><b>' + esc(n) + '</b> ' +\n"
    "      '<button class=\"sec sm danger\" onclick=\"unpublishPlugin(\\'' + n + '\\')\">下架</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  box.innerHTML = html;\n"
    "}\n"
    "\n"
    "async function publishPlugin(){\n"
    "  const name = $('pl-name').value.trim(), body = $('pl-body').value;\n"
    "  if(!name || !body){ if($('pl-stat')) $('pl-stat').textContent = '需要 name 和 body'; return; }\n"
    "  const caps = ($('pl-caps').value || '').split(',').map(s=>s.trim()).filter(Boolean);\n"
    "  const r = await call('POST', '/v1/plugins/publish',\n"
    "    {name, description:$('pl-desc').value, kind:$('pl-kind').value, body, capabilities:caps});\n"
    "  if($('pl-stat')) $('pl-stat').textContent = (r.obj && r.obj.ok) ? '已发布' : ('失败 ' + ((r.obj && r.obj.error) || r.status));\n"
    "  if(r.obj && r.obj.ok){ $('pl-name').value=''; $('pl-desc').value=''; $('pl-body').value=''; $('pl-caps').value=''; }\n"
    "  loadPluginMarket();\n"
    "}\n"
    "\n"
    "async function unpublishPlugin(n){\n"
    "  await call('DELETE', '/v1/plugins/market/' + encodeURIComponent(n));\n"
    "  loadPluginMarket();\n"
    "}\n"
    "\n"
    "/* ================= 插件自生成 ================= */\n"
    "\n"
    "async function pluginGenerate(){\n"
    "  const desc = $('plugin-desc').value.trim();\n"
    "  const st = $('plugin-stat');\n"
    "  if(!desc){ if(st) st.textContent = '请输入能力描述'; return; }\n"
    "  if(st) st.textContent = '生成中…（分析→架构→生成→安全审计→注册）';\n"
    "  const r = await call('POST', '/v1/plugins/generate', {description: desc});\n"
    "  if(st) st.textContent = (r.obj && r.obj.ok) ? '✔ 已生成并注册' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "  renderJSON(r.obj, $('plugin-result'));\n"
    "  if(r.obj && r.obj.ok) load('plugins');\n"
    "}\n"
    "\n"
    "/* ================= IM ================= */\n"
    "\n"
    "let IM_ACTIVE = null;\n"
    "let WS = null;\n"
    "let IM_CHANNELS = [];\n"
    "\n"
    "function imCreate(){\n"
    "  const name = $('im-new').value.trim() || '新会话';\n"
    "  const isGroup = $('im-group').checked;\n"
    "  const members = $('im-members').value.split(',').map(s => s.trim()).filter(Boolean);\n"
    "  const body = {name: name, kind: isGroup ? 'group' : 'direct'};\n"
    "  if(members.length) body.members = members;\n"
    "  const sel = $('im-channel');\n"
    "  if(sel && sel.value){ body.channel = sel.value; }\n"
    "  call('POST', '/v1/im/sessions', body).then(() => {\n"
    "    $('im-new').value = ''; $('im-members').value = '';\n"
    "    renderIm();\n"
    "  });\n"
    "}\n"
    "\n"
    "function imDelete(id){\n"
    "  call('DELETE', '/v1/im/sessions/' + id).then(() => {\n"
    "    if(IM_ACTIVE === id) IM_ACTIVE = null;\n"
    "    renderIm();\n"
    "  });\n"
    "}\n"
    "\n"
    "async function loadChannels(){\n"
    "  const r = await call('GET', '/v1/im/channels');\n"
    "  IM_CHANNELS = (r.obj && Array.isArray(r.obj.channels)) ? r.obj.channels : [];\n"
    "  const st = $('channels-stat');\n"
    "  if(st) st.textContent = IM_CHANNELS.length + ' 个渠道';\n"
    "  return IM_CHANNELS;\n"
    "}\n"
    "\n"
    "async function renderChannels(){\n"
    "  await loadChannels();\n"
    "  const box = $('channels-list');\n"
    "  if(!box) return;\n"
    "  if(!IM_CHANNELS.length){\n"
    "    box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无渠道</span>';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = '';\n"
    "  IM_CHANNELS.forEach(ch => {\n"
    "    const div = document.createElement('div');\n"
    "    div.className = 'im-session';\n"
    "    div.style.justifyContent = 'space-between';\n"
    "    const left = document.createElement('span');\n"
    "    left.style.cssText = 'display:flex;align-items:center;gap:6px;min-width:0;flex:1';\n"
    "    const t = document.createElement('span'); t.className = 'badge badge-warn'; t.textContent = ch.type;\n"
    "    const nm = document.createElement('span'); nm.className = 'name'; nm.textContent = ch.name;\n"
    "    nm.title = ch.endpoint || '';\n"
    "    if(!ch.enabled) nm.style.opacity = '0.5';\n"
    "    left.appendChild(t); left.appendChild(nm); div.appendChild(left);\n"
    "    const ops = document.createElement('span'); ops.style.cssText='display:flex;gap:4px';\n"
    "    const send = document.createElement('button'); send.textContent = '发'; send.title='发送测试消息到此渠道';\n"
    "    send.onclick = (e)=>{ e.stopPropagation(); channelSendTest(ch.name); };\n"
    "    const del = document.createElement('button'); del.textContent = '✕'; del.title='删除渠道'; del.className='del';\n"
    "    del.onclick = (e)=>{ e.stopPropagation(); channelRemove(ch.name); };\n"
    "    ops.appendChild(send); ops.appendChild(del); div.appendChild(ops);\n"
    "    box.appendChild(div);\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelAdd(){\n"
    "  const name = $('c-name').value.trim();\n"
    "  const type = $('c-type').value;\n"
    "  const endpoint = $('c-endpoint').value.trim();\n"
    "  const token = $('c-token').value.trim();\n"
    "  const target = $('c-target').value.trim();\n"
    "  const enabled = !!$('c-enabled').checked;\n"
    "  if(!name || !endpoint) return;\n"
    "  const body = {name, type, endpoint, enabled};\n"
    "  if(token) body.token = token;\n"
    "  if(target) body.target = target;\n"
    "  call('POST', '/v1/im/channels', body).then(r => {\n"
    "    if(r.obj && (r.obj.ok || r.obj.error === undefined)){\n"
    "      $('c-name').value=''; $('c-endpoint').value=''; $('c-token').value=''; $('c-target').value='';\n"
    "      renderIm(); renderChannels();\n"
    "    }\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelRemove(name){\n"
    "  call('DELETE', '/v1/im/channels/' + encodeURIComponent(name)).then(() => {\n"
    "    renderIm(); renderChannels();\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelSendTest(name){\n"
    "  call('POST', '/v1/im/channels/' + encodeURIComponent(name) + '/send', {text: '测试消息 来自 cognitive-os-agent 控制台'})\n"
    "    .then(() => toast('✉️ 已发送测试消息到 ' + name));\n"
    "}\n"
    "\n"
    "function imSelect(id){\n"
    "  IM_ACTIVE = id;\n"
    "  document.querySelectorAll('.im-session').forEach(s => s.classList.toggle('on', s.dataset.id === String(id)));\n"
    "  renderImThread();\n"
    "}\n"
    "\n"
    "function appendImMessage(m){\n"
    "  const t = $('im-thread');\n"
    "  if(!t) return;\n"
    "  const d = new Date(m.ts_ms || Date.now());\n"
    "  const time = d.getHours() + ':' + String(d.getMinutes()).padStart(2, '0');\n"
    "  const isMine = (m.role === 'user') && (!m.sender || m.sender === 'me');\n"
    "  const div = document.createElement('div');\n"
    "  div.className = 'im-msg ' + (isMine ? 'user' : 'assistant');\n"
    "  div.textContent = m.content || '';\n"
    "  const meta = document.createElement('div');\n"
    "  meta.className = 'meta';\n"
    "  const who = m.sender || (m.role === 'user' ? 'user' : 'assistant');\n"
    "  meta.textContent = who + ' · ' + time;\n"
    "  div.appendChild(meta);\n"
    "  t.appendChild(div);\n"
    "  t.scrollTop = t.scrollHeight;\n"
    "}\n"
    "\n"
    "async function renderImThread(){\n"
    "  const t = $('im-thread');\n"
    "  if(!t) return;\n"
    "  if(IM_ACTIVE === null){\n"
    "    t.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">选择一个会话开始聊天</span>';\n"
    "    return;\n"
    "  }\n"
    "  t.innerHTML = '<span class=\"muted\"><span class=\"spin\"></span> 加载中…</span>';\n"
    "  const r = await call('GET', '/v1/im/sessions/' + IM_ACTIVE + '/messages');\n"
    "  t.innerHTML = '';\n"
    "  if(Array.isArray(r.obj)){\n"
    "    r.obj.forEach(m => appendImMessage(m));\n"
    "  }\n"
    "}\n"
    "\n"
    "async function renderIm(){\n"
    "  const list = $('im-sessions');\n"
    "  if(!list) return;\n"
    "  await loadChannels();\n"
    "  const sel = $('im-channel');\n"
    "  if(sel){\n"
    "    sel.innerHTML = '<option value=\"\">无关联渠道</option>';\n"
    "    IM_CHANNELS.forEach(c => {\n"
    "      const o = document.createElement('option'); o.value = c.name; o.textContent = c.name + ' (' + c.type + ')';\n"
    "      sel.appendChild(o);\n"
    "    });\n"
    "  }\n"
    "  const g = $('im-group');\n"
    "  if(g && !g.dataset.bound){\n"
    "    g.dataset.bound = '1';\n"
    "    g.addEventListener('change', () => { const el = $('im-members'); if(el) el.hidden = !g.checked; });\n"
    "  }\n"
    "  const r = await call('GET', '/v1/im/sessions');\n"
    "  const sessions = (r.obj && Array.isArray(r.obj.sessions)) ? r.obj.sessions : [];\n"
    "  list.innerHTML = '';\n"
    "  if(!sessions.length){\n"
    "    list.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无会话，创建第一个吧</span>';\n"
    "    return;\n"
    "  }\n"
    "  sessions.forEach(s => {\n"
    "    const isGroup = s.kind === 'group';\n"
    "    const div = document.createElement('div');\n"
    "    div.className = 'im-session' + (s.id === IM_ACTIVE ? ' on' : '');\n"
    "    div.dataset.id = s.id;\n"
    "    div.onclick = () => imSelect(s.id);\n"
    "    const name = document.createElement('span');\n"
    "    name.className = 'name';\n"
    "    name.textContent = (s.name || ('#' + s.id)) + ' · ' + (s.messages || 0);\n"
    "    if(isGroup) name.textContent += ' · ' + ((s.members || []).length) + '人';\n"
    "    const badge = document.createElement('span');\n"
    "    badge.className = 'badge ' + (isGroup ? 'badge-ok' : 'badge-warn');\n"
    "    badge.textContent = isGroup ? '群' : '单';\n"
    "    if(s.channel){\n"
    "      const ch = document.createElement('span');\n"
    "      ch.className = 'badge badge-accent';\n"
    "      ch.textContent = '渠道:' + s.channel;\n"
    "      ch.title = '关联外部渠道';\n"
    "      name.appendChild(ch);\n"
    "    }\n"
    "    const del = document.createElement('button');\n"
    "    del.className = 'del';\n"
    "    del.textContent = '✕';\n"
    "    del.title = '删除会话';\n"
    "    del.onclick = (e) => { e.stopPropagation(); imDelete(s.id); };\n"
    "    const left = document.createElement('span');\n"
    "    left.style.cssText = 'display:flex;align-items:center;gap:6px;min-width:0;flex:1';\n"
    "    left.appendChild(badge);\n"
    "    left.appendChild(name);\n"
    "    div.appendChild(left);\n"
    "    div.appendChild(del);\n"
    "    list.appendChild(div);\n"
    "  });\n"
    "  renderChannels();\n"
    "  renderImThread();\n"
    "}\n"
    "\n"
    "function imSend(){\n"
    "  const input = $('im-input');\n"
    "  let content = input.value.trim();\n"
    "  if(!content || IM_ACTIVE === null) return;\n"
    "  let sender = 'me';\n"
    "  const m = content.match(/^@(\\S+)\\s+/);\n"
    "  if(m){ sender = m[1]; content = content.slice(m[0].length); }\n"
    "  if(!content) return;\n"
    "  input.value = '';\n"
    "  const payload = {type:'im.send', session_id: IM_ACTIVE, content, sender};\n"
    "  if(WS && WS.readyState === WebSocket.OPEN){\n"
    "    WS.send(JSON.stringify(payload));\n"
    "  } else {\n"
    "    call('POST', '/v1/im/sessions/' + IM_ACTIVE + '/messages', {role:'user', content, sender}).then(r => {\n"
    "      if(r.obj && r.obj.ok) renderImThread();\n"
    "    });\n"
    "  }\n"
    "}\n"
    "\n"
    "async function imSearch(){\n"
    "  const q = $('im-search').value.trim();\n"
    "  const box = $('im-search-results');\n"
    "  if(!q){ if(box) box.innerHTML = ''; return; }\n"
    "  const r = await call('GET', '/v1/im/search?q=' + encodeURIComponent(q));\n"
    "  const hits = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!box) return;\n"
    "  if(!hits.length){\n"
    "    box.innerHTML = '<div class=\"muted\" style=\"font-size:12px;margin:0 0 8px\">无匹配</div>';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = '<div class=\"chips\" style=\"margin-bottom:8px\">' + hits.map(h =>\n"
    "    '<button class=\"chip\" onclick=\"imSelect(' + h.session_id + ')\" title=\"' + esc(h.content) + '\">' +\n"
    "    '<b>' + esc(h.session_name || ('#' + h.session_id)) + '</b><span>' + esc(h.content) + '</span></button>'\n"
    "  ).join('') + '</div>';\n"
    "}\n"
    "\n"
    "/* ================= WebSocket 实时推送 ================= */\n"
    "\n"
    "function wsConnect(){\n"
    "  try {\n"
    "    const proto = location.protocol === 'https:' ? 'wss' : 'ws';\n"
    "    WS = new WebSocket(proto + '://' + location.host + '/ws');\n"
    "    WS.onmessage = (e) => {\n"
    "      try {\n"
    "        const m = JSON.parse(e.data);\n"
    "        if(m.type === 'im.message'){\n"
    "          if(current === 'im' && IM_ACTIVE === m.session_id){\n"
    "            appendImMessage(m);\n"
    "          } else {\n"
    "            toast('📩 新消息: ' + ((m.role === 'user') ? '用户' : '助手'));\n"
    "          }\n"
    "        } else if(m.type === 'event' && m.source === 'flow'){\n"
    "          const el = $('flow-out');\n"
    "          if(el && m.payload){\n"
    "            const p = m.payload;\n"
    "            let line = '';\n"
    "            if(p.stage === 'execute') line = '→ [' + (p.node || '') + ':' + (p.agent || '') + '] ' + (p.detail || '');\n"
    "            else if(p.stage === 'done') line = '✓ [' + (p.node || '') + ':' + (p.agent || '') + '] ' + (p.detail || '完成');\n"
    "            if(line) el.textContent += (el.textContent ? '\\n' : '') + line;\n"
    "          }\n"
    "        } else if(m.type === 'event' && CHAT_BUSY){\n"
    "          const st = $('chat-status');\n"
    "          if(st && m.payload){\n"
    "            if(m.payload.plan) st.textContent = '第 ' + (CHAT_ROUND = (CHAT_ROUND||0) + 1) + ' 轮：规划中…';\n"
    "            else if(m.payload.result) st.textContent = '第 ' + (CHAT_ROUND||1) + ' 轮：动作结果已回传';\n"
    "          }\n"
    "        }\n"
    "      } catch(err) { /* ignore non-JSON */ }\n"
    "    };\n"
    "    WS.onclose = () => { setTimeout(wsConnect, 3000); };\n"
    "    WS.onerror = () => { try { WS.close(); } catch(e) {} };\n"
    "  } catch(e) { /* ws unsupported */ }\n"
    "}\n"
    "\n"
    "/* ================= 对话（连续多轮聊天） ================= */\n"
    "\n"
    "async function loadChat(){\n"
    "  const box = $('chat-box'); if(!box) return;\n"
    "  const r = await call('GET', '/v1/chat/history');\n"
    "  const turns = (r.obj && Array.isArray(r.obj.turns)) ? r.obj.turns : [];\n"
    "  box.innerHTML = '';\n"
    "  turns.forEach(t => { if(t.q) chatAddBubble('user', t.q); if(t.a) chatAddBubble('bot', t.a); });\n"
    "  chatScroll();\n"
    "  loadUploads();\n"
    "}\n"
    "\n"
    "function chatAddBubble(role, text){\n"
    "  const box = $('chat-box'); if(!box) return;\n"
    "  const wrap = document.createElement('div');\n"
    "  wrap.style.cssText = role === 'user'\n"
    "    ? 'align-self:flex-end;max-width:85%;background:var(--accent,#3b82f6);color:#fff;border-radius:12px 12px 2px 12px;padding:8px 12px;white-space:pre-wrap;word-break:break-word'\n"
    "    : 'align-self:flex-start;max-width:92%;background:var(--card2,#1f2430);border:1px solid var(--border,#333);border-radius:12px 12px 12px 2px;padding:8px 12px';\n"
    "  if(role === 'bot'){\n"
    "    const pre = document.createElement('pre');\n"
    "    pre.style.cssText = 'margin:0;white-space:pre-wrap;word-break:break-word;font-size:12.5px';\n"
    "    pre.textContent = text;\n"
    "    wrap.appendChild(pre);\n"
    "  } else {\n"
    "    wrap.textContent = text;\n"
    "  }\n"
    "  box.appendChild(wrap);\n"
    "  chatScroll();\n"
    "  return wrap;\n"
    "}\n"
    "\n"
    "function chatScroll(){\n"
    "  const box = $('chat-box');\n"
    "  if(box) box.scrollTop = box.scrollHeight;\n"
    "}\n"
    "\n"
    "let CHAT_BUSY = false;\n"
    "let CHAT_ROUND = 0;\n"
    "\n"
    "async function chatSend(){\n"
    "  if(CHAT_BUSY) return;\n"
    "  const input = $('chat-input');\n"
    "  const msg = input ? input.value.trim() : '';\n"
    "  if(!msg) return;\n"
    "  const st = $('chat-status');\n"
    "  CHAT_BUSY = true;\n"
    "  CHAT_ROUND = 0;\n"
    "  input.value = '';\n"
    "  chatAddBubble('user', msg);\n"
    "  const bot = chatAddBubble('bot', '…');\n"
    "  const c = await call('POST', '/v1/chat', {message: msg});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    bot.querySelector('pre').textContent = '提交失败: ' + (c.text || ('HTTP ' + c.status));\n"
    "    CHAT_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; i < 600; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(st) st.textContent = (t && t.status && t.status !== 'DONE') ? ('状态: ' + t.status) : '';\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      bot.querySelector('pre').textContent = (t.output && t.output.trim()) ? t.output : ('(' + t.status + '，无输出)');\n"
    "      if(st) st.textContent = '';\n"
    "      CHAT_BUSY = false;\n"
    "      chatScroll();\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  }\n"
    "  bot.querySelector('pre').textContent = '(等待超时，任务仍在后台执行；可在 Tasks 页查看)';\n"
    "  CHAT_BUSY = false;\n"
    "}\n"
    "\n"
    "async function uploadFile(inp){\n"
    "  const f = inp.files && inp.files[0];\n"
    "  if(!f) return;\n"
    "  const st = $('chat-status');\n"
    "  if(st) st.textContent = '上传中: ' + f.name + '…';\n"
    "  try {\n"
    "    const resp = await fetch('/v1/upload?name=' + encodeURIComponent(f.name), {method:'POST', body: f});\n"
    "    const obj = await resp.json().catch(() => ({}));\n"
    "    if(resp.ok && obj.ok) toast('已上传 ' + obj.name + (obj.chunks ? ('（' + obj.chunks + ' 块入库）') : ''));\n"
    "    else toast('上传失败: ' + (obj.error || ('HTTP ' + resp.status)));\n"
    "  } catch(e) { toast('上传失败: ' + e); }\n"
    "  inp.value = '';\n"
    "  if(st) st.textContent = '';\n"
    "  loadUploads();\n"
    "}\n"
    "\n"
    "async function loadUploads(){\n"
    "  const el = $('uploads-list'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/uploads');\n"
    "  const files = (r.obj && Array.isArray(r.obj.files)) ? r.obj.files : [];\n"
    "  el.innerHTML = files.length\n"
    "    ? files.map(f => '<span class=\"chip\">' + esc(f.name) + ' <span class=\"muted\">(' + (f.size/1024).toFixed(1) + ' KB)</span> <button class=\"sec sm\" onclick=\"delUpload(\\'' + esc(f.name).replace(/'/g,\"\\\\'\") + '\\')\">✕</button></span>').join('')\n"
    "    : '<span class=\"muted\">（暂无上传）</span>';\n"
    "}\n"
    "\n"
    "async function delUpload(name){\n"
    "  const r = await call('DELETE', '/v1/uploads/' + encodeURIComponent(name));\n"
    "  if(r.status === 200) { toast('已删除 ' + name); loadUploads(); }\n"
    "  else toast('删除失败');\n"
    "}\n"
    "\n"
    "/* Enter 发送 */\n"
    "document.addEventListener('keydown', (e) => {\n"
    "  if(e.key === 'Enter' && !e.shiftKey && e.target && e.target.id === 'chat-input'){\n"
    "    e.preventDefault();\n"
    "    chatSend();\n"
    "  }\n"
    "});\n"
    "\n"
    "/* ================= Flow（自动编排 + 手写 DAG） ================= */\n"
    "\n"
    "let FLOW_BUSY = false;\n"
    "\n"
    "/* 生成 DAG：LLM 分解总任务 → 填入下方编辑器（不执行，可修改） */\n"
    "async function flowGen(){\n"
    "  const input = $('flow-task'), st = $('flow-gen-status'), ta = $('flow-json');\n"
    "  if(!input || !st) return;\n"
    "  const task = input.value.trim();\n"
    "  if(!task){ st.textContent = '请先输入总任务'; return; }\n"
    "  st.textContent = '分解中…';\n"
    "  const c = await call('POST', '/v1/flows/decompose', {task});\n"
    "  if(c.status === 200 && c.obj && c.obj.dag){\n"
    "    if(ta) ta.value = JSON.stringify(c.obj.dag, null, 2);\n"
    "    st.textContent = '已生成，可在下方修改后执行';\n"
    "  } else {\n"
    "    st.textContent = '生成失败: ' + ((c.obj && c.obj.error) || c.text || ('HTTP ' + c.status));\n"
    "  }\n"
    "}\n"
    "\n"
    "/* 自动执行：分解→执行→综合答案一步完成 */\n"
    "async function flowAuto(){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const input = $('flow-task'), st = $('flow-gen-status'), out = $('flow-out');\n"
    "  if(!input) return;\n"
    "  const task = input.value.trim();\n"
    "  if(!task){ if(st) st.textContent = '请先输入总任务'; return; }\n"
    "  FLOW_BUSY = true;\n"
    "  if(st) st.textContent = '已提交（分解→执行→综合）…';\n"
    "  if(out) out.textContent = '';\n"
    "  const c = await call('POST', '/v1/orchestrate', {task});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    if(st) st.textContent = '提交失败: ' + (c.text || ('HTTP ' + c.status));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; i < 600; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(st && t && t.status && t.status !== 'DONE') st.textContent = '状态: ' + t.status;\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      FLOW_LAST_OUTPUT = t.output || '';\n"
    "      if(out) out.textContent = FLOW_LAST_OUTPUT ? ('—— 综合答案 ——\\n' + FLOW_LAST_OUTPUT) : '(无输出)';\n"
    "      if(st) st.textContent = '';\n"
    "      FLOW_BUSY = false;\n"
    "      loadFlow();\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  }\n"
    "  if(st) st.textContent = '(等待超时，任务仍在后台执行)';\n"
    "  FLOW_BUSY = false;\n"
    "}\n"
    "\n"
    "/* ================= 策略规则 ================= */\n"
    "\n"
    "let POLICY_TOOLS_LOADED = false;\n"
    "async function loadPolicyTools(){\n"
    "  const sel = $('pol-tool'); if(!sel) return;\n"
    "  if(POLICY_TOOLS_LOADED) return;\n"
    "  const r = await call('GET', '/v1/tools');\n"
    "  const tools = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!tools.length) return;\n"
    "  const cur = sel.value || '*';\n"
    "  sel.innerHTML = '<option value=\"*\">*</option>' +\n"
    "    tools.map(t => '<option value=\"' + esc(t.name) + '\">' + esc(t.name) + '</option>').join('');\n"
    "  sel.value = [...sel.options].some(o => o.value === cur) ? cur : '*';\n"
    "  POLICY_TOOLS_LOADED = true;\n"
    "}\n"
    "\n"
    "async function loadPolicy(){\n"
    "  const el = $('pol-list'); if(!el) return;\n"
    "  loadPolicyTools();\n"
    "  const r = await call('GET', '/v1/policy/rules');\n"
    "  const rules = (r.obj && r.obj.rules) ? r.obj.rules : [];\n"
    "  if(!rules.length){\n"
    "    el.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无规则（默认全放行）</span>';\n"
    "    return;\n"
    "  }\n"
    "  const parts = [];\n"
    "  for(const g of rules){\n"
    "    const deny = g.action === 'deny';\n"
    "    const color = deny ? '#e74c3c' : (g.action === 'ask' ? '#f39c12' : '#27ae60');\n"
    "    parts.push('<div style=\"display:flex;align-items:center;gap:8px;margin:6px 0\">' +\n"
    "      '<span style=\"font-family:monospace;color:' + color + ';font-weight:600\">' + esc(g.action) + '</span>' +\n"
    "      '<span style=\"font-family:monospace\">' + esc(g.tool) + '</span>' +\n"
    "      (g.reason ? '<span class=\"muted\" style=\"font-size:12px\">' + esc(g.reason) + '</span>' : '') +\n"
    "      '<span style=\"flex:1\"></span>' +\n"
    "      '<button class=\"sec sm\" onclick=\"policyDelete(' + g.index + ')\">删除</button>' +\n"
    "      '</div>');\n"
    "  }\n"
    "  el.innerHTML = parts.join('');\n"
    "}\n"
    "\n"
    "async function policyAdd(){\n"
    "  const tool = $('pol-tool'), act = $('pol-action'), reason = $('pol-reason'), st = $('pol-stat');\n"
    "  if(!tool || !act) return;\n"
    "  const t = tool.value.trim();\n"
    "  if(!t){ if(st) st.textContent = 'tool 名不能为空'; return; }\n"
    "  const c = await call('POST', '/v1/policy/rules',\n"
    "    {tool: t, action: act.value, reason: reason ? reason.value.trim() : ''});\n"
    "  if(c.status === 200){\n"
    "    if(st) st.textContent = '已添加' + (c.obj && c.obj.saved ? '并持久化' : '（持久化失败，重启会丢失）');\n"
    "    tool.value = '*'; if(reason) reason.value = '';\n"
    "    loadPolicy();\n"
    "  } else {\n"
    "    if(st) st.textContent = '添加失败: ' + (c.text || ('HTTP ' + c.status));\n"
    "  }\n"
    "}\n"
    "\n"
    "async function policyDelete(idx){\n"
    "  const c = await call('DELETE', '/v1/policy/rules/' + idx);\n"
    "  if(c.status === 200) loadPolicy();\n"
    "  else toast('删除失败');\n"
    "}\n"
    "\n"
    "/* ================= Flow DAG 执行 ================= */\n"
    "\n"
    "async function loadFlow(){\n"
    "  const el = $('flow-board'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/blackboard');\n"
    "  const facts = (r.obj && r.obj.facts) ? r.obj.facts : {};\n"
    "  const parts = [];\n"
    "  for(const k of Object.keys(facts)){\n"
    "    if(k === 'flow/trace' || k.indexOf('flow/') === 0){\n"
    "      parts.push('<div style=\"margin:6px 0\"><b>' + esc(k) + '</b>' +\n"
    "        '<pre style=\"margin:2px 0;white-space:pre-wrap;font-size:12px\">' +\n"
    "        esc(String(facts[k]).slice(0, 1200)) + '</pre></div>');\n"
    "    }\n"
    "  }\n"
    "  el.innerHTML = parts.length ? parts.join('')\n"
    "    : '<span class=\"muted\" style=\"font-size:12px\">暂无 Flow 记录</span>';\n"
    "}\n"
    "\n"
    "let FLOW_LAST_OUTPUT = '';\n"
    "\n"
    "/* 把 Flow 执行结果 + 追加指令交给 LLM（走 /v1/chat，保留对话上下文） */\n"
    "async function flowChat(promptPrefix, statusEl){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const out = $('flow-out'), st = statusEl, inp = $('flow-follow');\n"
    "  if(!FLOW_LAST_OUTPUT){\n"
    "    if(st) st.textContent = '请先执行 Flow（或加载黑板记录）';\n"
    "    return;\n"
    "  }\n"
    "  FLOW_BUSY = true;\n"
    "  if(st) st.textContent = 'LLM 处理中…';\n"
    "  const tail = FLOW_LAST_OUTPUT.length > 3000 ? FLOW_LAST_OUTPUT.slice(-3000) : FLOW_LAST_OUTPUT;\n"
    "  const message = promptPrefix.replace('%RESULTS%', tail) + ((inp && inp.value.trim()) ? ('\\n\\n' + inp.value.trim()) : '');\n"
    "  const c = await call('POST', '/v1/chat', {message});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    if(st) st.textContent = '提交失败: ' + (c.text || ('HTTP ' + c.status));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; i < 600; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(st && t && t.status && t.status !== 'DONE') st.textContent = '状态: ' + t.status;\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      if(out) out.textContent = (out.textContent ? out.textContent + '\\n\\n' : '') + '—— LLM 回答 ——\\n' + (t.output || '(无输出)');\n"
    "      if(st) st.textContent = '';\n"
    "      if(inp) inp.value = '';\n"
    "      FLOW_BUSY = false;\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  }\n"
    "  if(st) st.textContent = '(等待超时，任务仍在后台执行)';\n"
    "  FLOW_BUSY = false;\n"
    "}\n"
    "\n"
    "/* LLM 综合 Flow 各节点结果为最终结论 */\n"
    "function flowMerge(){\n"
    "  flowChat('请综合以下 Flow 执行结果，给出最终结论（直接回答，不要复述过程）：\\n\\n%RESULTS%', $('flow-status'));\n"
    "}\n"
    "\n"
    "/* 继续对话：带着 Flow 结果追问 */\n"
    "function flowFollow(){\n"
    "  flowChat('以下是刚才 Flow 的执行结果：\\n\\n%RESULTS%\\n\\n请基于以上结果继续。', $('flow-follow-status'));\n"
    "}\n"
    "\n"
    "async function flowRun(){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const ta = $('flow-json'), st = $('flow-status'), out = $('flow-out');\n"
    "  if(!ta) return;\n"
    "  let dag;\n"
    "  try { dag = JSON.parse(ta.value); }\n"
    "  catch(e){ if(st) st.textContent = 'JSON 解析失败: ' + e.message; return; }\n"
    "  if(!dag.nodes){ if(st) st.textContent = '缺少 nodes 数组'; return; }\n"
    "  FLOW_BUSY = true;\n"
    "  if(st) st.textContent = '提交中…';\n"
    "  if(out) out.textContent = '';\n"
    "  const c = await call('POST', '/v1/flows', dag);\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    if(st) st.textContent = '提交失败: ' + (c.obj && c.obj.error ? c.obj.error : (c.text || ('HTTP ' + c.status)));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; i < 600; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(st) st.textContent = (t && t.status && t.status !== 'DONE') ? ('状态: ' + t.status) : '';\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      FLOW_LAST_OUTPUT = t.output || '';\n"
    "      if(out) out.textContent = FLOW_LAST_OUTPUT ? ('—— Flow 输出 ——\\n' + FLOW_LAST_OUTPUT) : '(无输出)';\n"
    "      if(st) st.textContent = '';\n"
    "      FLOW_BUSY = false;\n"
    "      loadFlow();\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  }\n"
    "  if(st) st.textContent = '(等待超时，任务仍在后台执行)';\n"
    "  FLOW_BUSY = false;\n"
    "}\n"
    "\n"
    "/* ================= 模型路由 ================= */\n"
    "\n"
    "const PROVIDER_PRESETS = {\n"
    "  mock:      {provider:'mock',      base:'',                                                                 model:''},\n"
    "  openai:    {provider:'openai',    base:'https://api.openai.com/v1',                                        model:'gpt-4o'},\n"
    "  anthropic: {provider:'anthropic', base:'https://api.anthropic.com',                                        model:'claude-sonnet-4-6'},\n"
    "  deepseek:  {provider:'openai',    base:'https://api.deepseek.com/v1',                                      model:'deepseek-chat'},\n"
    "  deepseek_a:{provider:'anthropic', base:'https://api.deepseek.com/anthropic',                               model:'deepseek-v4-pro'},\n"
    "  ollama:    {provider:'openai',    base:'http://localhost:11434/v1',                                        model:'llama3'},\n"
    "  gemini:    {provider:'openai',    base:'https://generativelanguage.googleapis.com/v1beta/openai',          model:'gemini-2.0-flash'},\n"
    "  groq:      {provider:'openai',    base:'https://api.groq.com/openai/v1',                                   model:'llama-3.3-70b-versatile'},\n"
    "  together:  {provider:'openai',    base:'https://api.together.xyz/v1',                                      model:'meta-llama/Llama-3.3-70B-Instruct-Turbo'},\n"
    "  vllm:      {provider:'openai',    base:'http://localhost:8080/v1',                                         model:''},\n"
    "};\n"
    "\n"
    "function presetProvider(){\n"
    "  return (PROVIDER_PRESETS[$('r-provider').value] || PROVIDER_PRESETS.openai).provider;\n"
    "}\n"
    "\n"
    "let ROUTES = [];\n"
    "let ACTIVE = {provider:'', model:'', api_key_set:false};\n"
    "\n"
    "let MODEL_PLAZA = [];\n"
    "\n"
    "async function loadModelPlaza(){\n"
    "  const box = $('model-plaza');\n"
    "  if(!box) return;\n"
    "  const r = await call('GET', '/v1/catalog/models');\n"
    "  MODEL_PLAZA = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!MODEL_PLAZA.length){ box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（目录为空）</span>'; return; }\n"
    "  box.innerHTML = MODEL_PLAZA.map((m, i) =>\n"
    "    '<div class=\"item\"><h3>' + esc(m.name) + '</h3><p>' + esc(m.note || '') + '</p>' +\n"
    "    '<div class=\"url\">' + esc(m.base_url) + ' · ' + esc(m.model || '任意模型') + '</div>' +\n"
    "    '<div class=\"hint\">' + (m.local\n"
    "        ? '本地运行 · 无需 key'\n"
    "        : 'key: ' + esc(m.key_hint || '')) +\n"
    "      (m.signup_url\n"
    "        ? ' <a href=\"' + esc(m.signup_url) + '\" target=\"_blank\" rel=\"noopener\">申请 key ↗</a>'\n"
    "        : '') + '</div>' +\n"
    "    '<div class=\"row\"><button class=\"sec sm\" onclick=\"modelPlazaUse(' + i + ')\">配置</button>' +\n"
    "    '<button class=\"sec sm\" onclick=\"modelPlazaTest(' + i + ')\">测试</button>' +\n"
    "    '<button class=\"sm\" onclick=\"modelPlazaSet(' + i + ')\">配置并设为当前</button></div></div>'\n"
    "  ).join('');\n"
    "  localStatus(null); /* refresh the local-runtime badges */\n"
    "}\n"
    "\n"
    "function modelPlazaFill(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  $('r-name').value = m.id;\n"
    "  $('r-base').value = m.base_url;\n"
    "  $('r-model').value = m.model;\n"
    "}\n"
    "\n"
    "function modelPlazaUse(i){\n"
    "  modelPlazaFill(i);\n"
    "  toast('已填入表单，填好 key（如需）后点 Add route');\n"
    "}\n"
    "\n"
    "async function modelPlazaSet(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  modelPlazaFill(i);\n"
    "  const key = ($('r-key') && $('r-key').value.trim()) || '';\n"
    "  const r = await call('POST', '/v1/config/llm', {provider: m.provider, base_url: m.base_url, model: m.model, api_key: key});\n"
    "  toast((r.obj && r.obj.ok) ? '已切换为 ' + (m.model || m.name) : '切换失败: ' + ((r.obj && r.obj.error) || r.status));\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function modelPlazaTest(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  const key = ($('r-key') && $('r-key').value.trim()) || '';\n"
    "  await testLlm({provider: m.provider, base_url: m.base_url, model: m.model, api_key: key},\n"
    "                (m.model || m.name) + ' ');\n"
    "}\n"
    "\n"
    "function sleep(ms){ return new Promise(r => setTimeout(r, ms)); }\n"
    "\n"
    "let LOCAL_ST = {};\n"
    "async function localStatus(engine){\n"
    "  const r = await call('GET', '/v1/local/status');\n"
    "  LOCAL_ST = (r.obj && typeof r.obj === 'object') ? r.obj : {};\n"
    "  const o = LOCAL_ST.ollama || {}, l = LOCAL_ST.llamacpp || {};\n"
    "  const b1 = $('loc-ollama');\n"
    "  if(b1){\n"
    "    b1.textContent = o.running ? '● 运行中' : (o.installed ? '已安装 · 未运行' : '未安装');\n"
    "    b1.className = 'badge ' + (o.running ? 'badge-ok' : (o.installed ? 'badge-warn' : 'badge-err'));\n"
    "  }\n"
    "  const b2 = $('loc-llamacpp');\n"
    "  if(b2){\n"
    "    b2.textContent = l.running ? '● 运行中' : '未检测到';\n"
    "    b2.className = 'badge ' + (l.running ? 'badge-ok' : 'badge-err');\n"
    "  }\n"
    "  const m = $('loc-msg');\n"
    "  if(m && engine) m.textContent = engine + ' 检测完成';\n"
    "}\n"
    "\n"
    "async function localStart(engine){\n"
    "  const m = $('loc-msg');\n"
    "  if(m) m.textContent = '正在启动 ' + engine + '…';\n"
    "  const r = await call('POST', '/v1/local/start', {engine});\n"
    "  const o = r.obj || {};\n"
    "  if(o.ok){\n"
    "    const running = o.already_running || o.spawned;\n"
    "    const note = o.already_running ? (engine + ' 已在运行') : (o.note || ('已启动 ' + engine));\n"
    "    if(m) m.textContent = note;\n"
    "    toast(note);\n"
    "    /* poll status for up to ~6s so the badge flips to running when ready */\n"
    "    for(let i = 0; i < 6 && !running; i++){ await sleep(1000); await localStatus(null); }\n"
    "    if(running) await localStatus(null);\n"
    "  } else {\n"
    "    const note = o.error || ('启动 ' + engine + ' 失败');\n"
    "    if(m) m.textContent = note;\n"
    "    toast(note);\n"
    "  }\n"
    "}\n"
    "\n"
    "async function loadModels(){\n"
    "  const r   = await call('GET', '/v1/routes');\n"
    "  const cfg = await call('GET', '/v1/config/llm');\n"
    "  ROUTES = Array.isArray(r.obj) ? r.obj : [];\n"
    "  ACTIVE = (cfg.obj && typeof cfg.obj === 'object') ? cfg.obj : ACTIVE;\n"
    "  loadModelPlaza();\n"
    "  const rp = $('r-provider');\n"
    "  if(rp && !rp.dataset.bound){\n"
    "    rp.dataset.bound = '1';\n"
    "    rp.addEventListener('change', () => {\n"
    "      const p = PROVIDER_PRESETS[$('r-provider').value] || PROVIDER_PRESETS.openai;\n"
    "      const rb = $('r-base'), rm = $('r-model');\n"
    "      if(rb) rb.value = p.base;\n"
    "      if(rm){ rm.placeholder = p.model || 'model (可选)'; if(!rm.value) rm.value = p.model; }\n"
    "    });\n"
    "  }\n"
    "  const st = $('models-stat');\n"
    "  if(st) st.textContent = 'active: ' + (ACTIVE.provider || '?')\n"
    "      + (ACTIVE.model ? ' / ' + ACTIVE.model : '')\n"
    "      + (ACTIVE.api_key_set ? '' : '（未配置 api_key）');\n"
    "  const t = $('routes-body');\n"
    "  if(!t) return;\n"
    "  if(!ROUTES.length){ t.innerHTML = '<tr><td colspan=\"7\" class=\"muted\">（暂无路由）</td></tr>'; return; }\n"
    "  const ap = ACTIVE.provider || '';\n"
    "  t.innerHTML = ROUTES.map((x, i) => {\n"
    "    const isActive = x.name === ap;\n"
    "    return '<tr class=\"' + (isActive ? 'active-row' : '') + '\">'\n"
    "      + '<td>' + esc(x.name || '') + (isActive ? ' <span class=\"badge badge-ok\">active</span>' : '') + '</td>'\n"
    "      + '<td>' + esc(x.provider || '') + '</td>'\n"
    "      + '<td>' + esc(x.model || '') + '</td>'\n"
    "      + '<td class=\"muted\">' + esc(x.base_url || '') + '</td>'\n"
    "      + '<td>' + (x.weight != null ? x.weight : 1) + '</td>'\n"
    "      + '<td>' + (x.calls != null ? x.calls : 0) + '</td>'\n"
    "      + '<td><button onclick=\"testRoute(' + i + ')\" class=\"sec sm\">Test</button> '\n"
    "      + '<button onclick=\"setActive(' + i + ')\" class=\"sec sm\"' + (isActive ? ' disabled' : '') + '>Set active</button> '\n"
    "      + '<button onclick=\"deleteRoute(' + i + ')\" class=\"sec sm danger\">Delete</button></td></tr>';\n"
    "  }).join('');\n"
    "}\n"
    "\n"
    "async function setActive(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  const st = $('models-stat'); if(st) st.textContent = 'switching…';\n"
    "  const r = await call('POST', '/v1/config/llm', {\n"
    "    provider: x.provider, base_url: x.base_url || '', model: x.model || '', api_key: x.api_key || ''\n"
    "  });\n"
    "  if(st) st.textContent = (r.obj && r.obj.ok)\n"
    "      ? 'switched to ' + (x.model || x.provider)\n"
    "      : (r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status;\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function deleteRoute(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  await call('DELETE', '/v1/routes/' + encodeURIComponent(x.name));\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function addRoute(){\n"
    "  const name = $('r-name').value.trim();\n"
    "  const provider = presetProvider();\n"
    "  const msg = $('routes-msg');\n"
    "  if(!name){ if(msg) msg.textContent = 'need name'; return; }\n"
    "  const body = {\n"
    "    name, provider,\n"
    "    base_url: $('r-base').value.trim(),\n"
    "    model: $('r-model').value.trim(),\n"
    "    api_key: $('r-key').value.trim()\n"
    "  };\n"
    "  const w = parseFloat($('r-weight').value);\n"
    "  if(!isNaN(w)) body.weight = w;\n"
    "  const r = await call('POST', '/v1/routes', body);\n"
    "  if(msg) msg.textContent = (r.status < 300) ? 'route saved'\n"
    "      : (r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status;\n"
    "  if(r.status < 300){\n"
    "    $('r-name').value = ''; $('r-base').value = ''; $('r-key').value = ''; $('r-model').value = '';\n"
    "  }\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* Test an arbitrary LLM config against the live provider (no switch, no persist). */\n"
    "async function testLlm(body, prefix){\n"
    "  prefix = prefix || '';\n"
    "  const st = $('models-stat'); if(st) st.textContent = '测试 ' + prefix + '请求中…';\n"
    "  const r = await call('POST', '/v1/config/llm/test', body);\n"
    "  const ok = r.obj && r.obj.ok;\n"
    "  const detail = (r.obj && (r.obj.reply || r.obj.error)) || ('HTTP ' + r.status);\n"
    "  if(st) st.textContent = (ok ? '✅ 测试通过 ' : '❌ 测试失败 ') + prefix + detail;\n"
    "  toast((ok ? '✅ ' : '❌ ') + prefix + detail);\n"
    "}\n"
    "\n"
    "async function testRoute(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  await testLlm({provider: x.provider, base_url: x.base_url || '', model: x.model || '', api_key: x.api_key || ''},\n"
    "                '路由 ' + x.name + ' ');\n"
    "}\n"
    "\n"
    "async function testForm(){\n"
    "  const provider = presetProvider();\n"
    "  await testLlm({\n"
    "    provider,\n"
    "    base_url: $('r-base').value.trim(),\n"
    "    model: $('r-model').value.trim(),\n"
    "    api_key: ($('r-key') && $('r-key').value.trim()) || ''\n"
    "  }, '表单配置 ');\n"
    "}\n"
    "\n"
    "/* ================= 导航 ================= */\n"
    "\n"
    "const TITLES = {dashboard:'Dashboard', chat:'对话', agents:'Agents', policy:'策略', flow:'Flow', models:'Models', mcp:'MCP', skills:'Skills', plugins:'Plugins', im:'IM', memory:'Memory', snapshots:'Execution', trace:'Monitor', cluster:'Cluster', metrics:'Metrics'};\n"
    "let current = 'dashboard';\n"
    "\n"
    "function switchPanel(p){\n"
    "  current = p;\n"
    "  document.querySelectorAll('#nav button').forEach(b => {\n"
    "    const on = b.dataset.p === p;\n"
    "    b.classList.toggle('on', on);\n"
    "    if(on) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current');\n"
    "  });\n"
    "  const t = $('pageTitle'); if(t) t.textContent = TITLES[p] || p;\n"
    "  $('content').innerHTML = panels[p];\n"
    "  load(p);\n"
    "  if(window.innerWidth < 900) toggleSidebar(false);\n"
    "}\n"
    "\n"
    "document.querySelectorAll('#nav button').forEach(b => {\n"
    "  b.addEventListener('click', () => switchPanel(b.dataset.p));\n"
    "});\n"
    "\n"
    "function toggleSidebar(force){\n"
    "  const open = typeof force === 'boolean' ? force : !$('sidebar').classList.contains('open');\n"
    "  $('sidebar').classList.toggle('open', open);\n"
    "  $('navToggle').setAttribute('aria-expanded', open ? 'true' : 'false');\n"
    "  $('backdrop').classList.toggle('on', open && window.innerWidth < 900);\n"
    "}\n"
    "$('navToggle').addEventListener('click', () => toggleSidebar());\n"
    "$('backdrop').addEventListener('click', () => toggleSidebar(false));\n"
    "\n"
    "$('btnRefresh').addEventListener('click', () => {\n"
    "  if(current === 'tasks'){ toast('已在 Tasks 页'); return; }\n"
    "  if(current === 'models') loadModels(); else load(current);\n"
    "  toast('已刷新');\n"
    "});\n"
    "\n"
    "/* ================= 主题 ================= */\n"
    "\n"
    "const THEMES = ['dark', 'light', 'ocean', 'forest', 'sunset'];\n"
    "function applyTheme(t){\n"
    "  if(!THEMES.includes(t)) t = 'dark';\n"
    "  document.body.dataset.theme = t;\n"
    "  try { localStorage.setItem('cognitive-os-agent-theme', t); } catch(e) {}\n"
    "  const sel = $('theme'); if(sel) sel.value = t;\n"
    "}\n"
    "$('theme').addEventListener('change', e => applyTheme(e.target.value));\n"
    "applyTheme(localStorage.getItem('cognitive-os-agent-theme') || 'dark');\n"
    "\n"
    "/* ================= 连接状态 ================= */\n"
    "\n"
    "async function pingServer(){\n"
    "  const r = await call('GET', '/v1/config/llm');\n"
    "  const ok = r.status !== 0;\n"
    "  const dot = $('connDot'), txt = $('connText');\n"
    "  if(dot){ dot.className = 'dot ' + (ok ? 'ok' : 'err'); }\n"
    "  if(txt) txt.textContent = ok ? '已连接' : '离线';\n"
    "}\n"
    "setInterval(pingServer, 8000);\n"
    "\n"
    "/* ================= 初始化 ================= */\n"
    "\n"
    "$('content').innerHTML = panels.dashboard;\n"
    "const imInput = $('im-input');\n"
    "if(imInput) imInput.addEventListener('keydown', e => { if(e.key === 'Enter') imSend(); });\n"
    "pingServer();\n"
    "wsConnect();\n"
    "loadDashboard();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
    ;
